    },
    {
      "trackId": "house",
      "name": "Front of house",
      "steps": [
        {
          "stepId": "setFOH",
          "name": "Set front of house — merch, bars, ushers",
          "task": "house",
          "duration": { "type": "fixed", "seconds": 3600 },
          "startTrigger": { "type": "programStartOffset", "offsetSeconds": 7200 }
